CREATE TABLE "a_research_report" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "info_code" varchar(50) NOT NULL, "ts_code" varchar(20) NULL, "stock_code" varchar(20) NULL, "stock_name" varchar(100) NULL, "publish_date" timestamp with time zone NULL, "title" varchar(500) NULL, "column" varchar(50) NULL, "count" integer NULL, "report_type" varchar(50) NULL, "encode_url" varchar(500) NULL, "market" varchar(20) NULL, "org_code" varchar(50) NULL, "org_name" varchar(200) NULL, "org_s_name" varchar(200) NULL, "org_type" varchar(50) NULL, "researcher" varchar(500) NULL, "author" varchar(500) NULL, "author_id" varchar(200) NULL, "em_rating_code" varchar(20) NULL, "em_rating_name" varchar(50) NULL, "em_rating_value" double precision NULL, "rating_change" varchar(50) NULL, "last_em_rating_code" varchar(20) NULL, "last_em_rating_name" varchar(50) NULL, "last_em_rating_value" double precision NULL, "s_rating_code" varchar(20) NULL, "s_rating_name" varchar(50) NULL, "industry_code" varchar(50) NULL, "industry_name" varchar(100) NULL, "em_industry_code" varchar(50) NULL, "indv_indu_code" varchar(50) NULL, "indv_indu_name" varchar(100) NULL, "indv_is_new" varchar(10) NULL, "indv_aim_price_t" double precision NULL, "indv_aim_price_l" double precision NULL, "predict_this_year_eps" double precision NULL, "predict_this_year_pe" double precision NULL, "predict_next_year_eps" double precision NULL, "predict_next_year_pe" double precision NULL, "predict_next_two_year_eps" double precision NULL, "predict_next_two_year_pe" double precision NULL, "predict_last_year_eps" double precision NULL, "predict_last_year_pe" double precision NULL, "actual_last_year_eps" double precision NULL, "actual_last_two_year_eps" double precision NULL, "new_purchase_date" varchar(30) NULL, "new_listing_date" varchar(30) NULL, "new_issue_price" double precision NULL, "new_pe_issue_a" double precision NULL, "attach_type" varchar(20) NULL, "attach_size" varchar(20) NULL, "attach_pages" varchar(20) NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_trade_cal" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "exchange" varchar(10) NOT NULL, "cal_date" date NOT NULL, "is_open" integer NOT NULL, "pretrade_date" date NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_paper_account" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_name" varchar(50) NOT NULL, "initial_capital" double precision NOT NULL, "cash" double precision NOT NULL, "total_assets" double precision NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_paper_position" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_name" varchar(50) NOT NULL, "ts_code" varchar(20) NOT NULL, "name" varchar(100) NULL, "volume" integer NOT NULL, "cost_basis" double precision NULL, "current_price" double precision NULL, "market_value" double precision NULL, "weight" double precision NULL, "unrealized_pnl" double precision NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_paper_transaction" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_name" varchar(50) NOT NULL, "trade_date" date NOT NULL, "ts_code" varchar(20) NOT NULL, "name" varchar(100) NULL, "direction" varchar(10) NOT NULL, "target_volume" integer NULL, "filled_volume" integer NULL, "price" double precision NULL, "amount" double precision NULL, "commission" double precision NULL, "stamp_tax" double precision NULL, "slippage_cost" double precision NULL, "total_cost" double precision NULL, "reason" varchar(200) NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_paper_nav" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_name" varchar(50) NOT NULL, "trade_date" date NOT NULL, "cash" double precision NULL, "market_value" double precision NULL, "total_assets" double precision NULL, "nav" double precision NOT NULL, "daily_pnl" double precision NULL, "daily_return" double precision NULL, "n_holdings" integer NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_industry_factor_config" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "industry_name" varchar(100) NOT NULL, "factor_name" varchar(50) NOT NULL, "weight" double precision NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_watchlist" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "ts_code" varchar(20) NOT NULL, "name" varchar(100) NULL, "notes" text NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_selection_result" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "date" date NOT NULL, "total" integer NOT NULL, "top_stocks" text NULL, "by_industry" text NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "a_factor_snapshot" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "date" date NOT NULL, "ts_code" varchar(20) NOT NULL, "score" double precision NULL, "factors" text NULL, "created_at" timestamp with time zone NOT NULL);

-- 3. UNIQUE INDEX（对应 models Meta.unique_together）
