CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_financial_indicator_ts_code_end_date" ON "a_financial_indicator" ("ts_code", "end_date");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_industry_class_ts_code_src_level_index_code_in_date" ON "a_industry_class" ("ts_code", "src", "level", "index_code", "in_date");
