CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_commodity_price_ts_code_trade_date" ON "a_commodity_price" ("ts_code", "trade_date");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_insider_transaction_ts_code_change_date_holder_name_hol" ON "a_insider_transaction" ("ts_code", "change_date", "holder_name", "holder_type");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_research_report_info_code" ON "a_research_report" ("info_code");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_trade_cal_exchange_cal_date" ON "a_trade_cal" ("exchange", "cal_date");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_paper_account_account_name" ON "a_paper_account" ("account_name");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_paper_position_account_name_ts_code" ON "a_paper_position" ("account_name", "ts_code");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_paper_nav_account_name_trade_date" ON "a_paper_nav" ("account_name", "trade_date");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_industry_factor_config_industry_name_factor_name" ON "a_industry_factor_config" ("industry_name", "factor_name");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_watchlist_ts_code" ON "a_watchlist" ("ts_code");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_selection_result_date" ON "a_selection_result" ("date");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_a_factor_snapshot_date_ts_code" ON "a_factor_snapshot" ("date", "ts_code");

